  "Eggplant": { hi: "बैंगन", gu: "રીંગણ" },
  "Butternut Squash": { hi: "बटरनट स्क्वैश", gu: "બટરનટ સ્ક્વોશ" },
  "Acorn Squash": { hi: "एकॉर्न स्क्वैश", gu: "એકોર્ન સ્ક્વોશ" },
  "Coconut": { hi: "नारियल", gu: "નાળિયેર" },
